-- Tannelli MySQL 8.0+ initial schema
-- Run with: mysql -u <user> -p <database> < database/schema.sql
CREATE DATABASE IF NOT EXISTS tannelli CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE tannelli;

CREATE TABLE users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL,
 first_name VARCHAR(100), last_name VARCHAR(100), phone VARCHAR(32), locale ENUM('en','fr','ar') NOT NULL DEFAULT 'en',
 role ENUM('customer','expert','seller','admin','support') NOT NULL DEFAULT 'customer', status ENUM('active','pending','suspended') NOT NULL DEFAULT 'active', profile_picture_url VARCHAR(1000), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);
CREATE TABLE addresses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,label VARCHAR(80),recipient_name VARCHAR(200),phone VARCHAR(32),line1 VARCHAR(255) NOT NULL,line2 VARCHAR(255),city VARCHAR(100) NOT NULL,state VARCHAR(100),postal_code VARCHAR(24),country_code CHAR(2) NOT NULL,is_default BOOLEAN DEFAULT FALSE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE sellers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,company_name VARCHAR(255) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,description TEXT,status ENUM('pending','active','suspended') DEFAULT 'pending',commission_rate DECIMAL(5,2) DEFAULT 10.00,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,parent_id BIGINT UNSIGNED NULL,name VARCHAR(140) NOT NULL,slug VARCHAR(160) NOT NULL UNIQUE,kind ENUM('plant','equipment') NOT NULL,description TEXT,sort_order INT DEFAULT 0,FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,seller_id BIGINT UNSIGNED NULL,category_id BIGINT UNSIGNED NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,short_description VARCHAR(500),description TEXT,kind ENUM('plant','equipment') NOT NULL,price DECIMAL(12,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'USD',stock_qty INT NOT NULL DEFAULT 0,status ENUM('draft','active','archived') DEFAULT 'draft',difficulty ENUM('easy','moderate','advanced'),light_requirement VARCHAR(100),climate VARCHAR(255),care_requirements TEXT,recommended_usage TEXT,average_rating DECIMAL(3,2) DEFAULT 0,reviews_count INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(seller_id) REFERENCES sellers(id),FOREIGN KEY(category_id) REFERENCES categories(id),INDEX(category_id,status),FULLTEXT(name,short_description,description));
CREATE TABLE product_variants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,sku VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(160),price DECIMAL(12,2) NOT NULL,stock_qty INT DEFAULT 0,attributes JSON,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE media_assets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,owner_user_id BIGINT UNSIGNED NULL,entity_type ENUM('product','expert','project','consultation','guide','review') NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,cloudinary_public_id VARCHAR(400) NOT NULL UNIQUE,secure_url VARCHAR(1000) NOT NULL,resource_type ENUM('image','video','raw') NOT NULL DEFAULT 'image',mime_type VARCHAR(100),width INT,height INT,alt_text VARCHAR(255),sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(entity_type,entity_id));
CREATE TABLE carts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,currency CHAR(3) DEFAULT 'USD',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE cart_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,cart_id BIGINT UNSIGNED NOT NULL,product_variant_id BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL DEFAULT 1,UNIQUE(cart_id,product_variant_id),FOREIGN KEY(cart_id) REFERENCES carts(id) ON DELETE CASCADE,FOREIGN KEY(product_variant_id) REFERENCES product_variants(id));
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_number VARCHAR(32) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,address_id BIGINT UNSIGNED NULL,status ENUM('pending','paid','processing','shipped','delivered','cancelled','refunded') DEFAULT 'pending',currency CHAR(3) NOT NULL,total DECIMAL(12,2) NOT NULL,payment_status ENUM('unpaid','authorized','paid','failed','refunded') DEFAULT 'unpaid',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(address_id) REFERENCES addresses(id));
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_variant_id BIGINT UNSIGNED NULL,seller_id BIGINT UNSIGNED NULL,name_snapshot VARCHAR(255) NOT NULL,sku_snapshot VARCHAR(100),unit_price DECIMAL(12,2) NOT NULL,quantity INT NOT NULL,total DECIMAL(12,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_variant_id) REFERENCES product_variants(id),FOREIGN KEY(seller_id) REFERENCES sellers(id));
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED NOT NULL,provider VARCHAR(60) NOT NULL,provider_payment_id VARCHAR(255) UNIQUE,amount DECIMAL(12,2) NOT NULL,currency CHAR(3) NOT NULL,status ENUM('pending','paid','failed','refunded') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE deliveries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,carrier VARCHAR(100),tracking_number VARCHAR(150),tracking_url VARCHAR(1000),status VARCHAR(50) DEFAULT 'pending',estimated_delivery DATE,delivered_at DATETIME,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE expert_profiles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,slug VARCHAR(180) NOT NULL UNIQUE,professional_category VARCHAR(120) NOT NULL,bio TEXT,experience_years SMALLINT,qualifications TEXT,languages JSON,location VARCHAR(255),consultation_price DECIMAL(12,2),rating DECIMAL(3,2) DEFAULT 0,reviews_count INT DEFAULT 0,availability JSON,status ENUM('pending','active','suspended','rejected') DEFAULT 'pending',verification_documents JSON,rejection_reason TEXT,verified_at DATETIME NULL,verified_by BIGINT UNSIGNED NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(verified_by) REFERENCES users(id));
CREATE TABLE expert_services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,expert_id BIGINT UNSIGNED NOT NULL,service_type ENUM('30_min','60_min','written_diagnosis','garden_design','care_plan','full_project') NOT NULL,title VARCHAR(150),price DECIMAL(12,2) NOT NULL,duration_minutes SMALLINT,active BOOLEAN DEFAULT TRUE,FOREIGN KEY(expert_id) REFERENCES expert_profiles(id) ON DELETE CASCADE);
CREATE TABLE consultation_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,assigned_expert_id BIGINT UNSIGNED NULL,location VARCHAR(255),plant_type VARCHAR(255),objective TEXT,space_details VARCHAR(255),sun_exposure VARCHAR(100),soil_info TEXT,water_availability VARCHAR(100),budget DECIMAL(12,2),status ENUM('submitted','matched','booked','in_progress','completed','cancelled') DEFAULT 'submitted',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES users(id),FOREIGN KEY(assigned_expert_id) REFERENCES expert_profiles(id));
CREATE TABLE consultations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id BIGINT UNSIGNED NOT NULL,service_id BIGINT UNSIGNED NOT NULL,scheduled_at DATETIME NULL,meeting_url VARCHAR(1000),status ENUM('booked','completed','cancelled','no_show') DEFAULT 'booked',recommendation TEXT,maintenance_schedule JSON,estimated_budget DECIMAL(12,2),FOREIGN KEY(request_id) REFERENCES consultation_requests(id),FOREIGN KEY(service_id) REFERENCES expert_services(id));
CREATE TABLE projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(200) NOT NULL,project_type ENUM('balcony','backyard','vegetable_garden','orchard','indoor','farm','other') DEFAULT 'other',location VARCHAR(255),budget DECIMAL(12,2),progress TINYINT UNSIGNED DEFAULT 0,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE project_tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,title VARCHAR(255) NOT NULL,due_date DATE,task_type ENUM('planting','watering','feeding','pruning','maintenance','other') DEFAULT 'other',completed_at DATETIME NULL,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE project_products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity INT DEFAULT 1,source ENUM('manual','expert_recommendation','order') DEFAULT 'manual',FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,expert_id BIGINT UNSIGNED NULL,rating TINYINT UNSIGNED NOT NULL,body TEXT,status ENUM('pending','published','rejected') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CHECK(rating BETWEEN 1 AND 5),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(expert_id) REFERENCES expert_profiles(id) ON DELETE CASCADE);
CREATE TABLE wishlists (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE product_questions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,question TEXT NOT NULL,answer TEXT,answered_by BIGINT UNSIGNED NULL,status ENUM('pending','published','hidden') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(answered_by) REFERENCES users(id));
CREATE TABLE articles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,author_id BIGINT UNSIGNED NULL,slug VARCHAR(180) NOT NULL UNIQUE,title VARCHAR(255) NOT NULL,excerpt TEXT,body LONGTEXT NOT NULL,category VARCHAR(120),locale ENUM('en','fr','ar') DEFAULT 'en',status ENUM('draft','published','archived') DEFAULT 'draft',published_at DATETIME NULL,FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE promotions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(64) UNIQUE,description VARCHAR(255),discount_type ENUM('percent','fixed') NOT NULL,discount_value DECIMAL(12,2) NOT NULL,starts_at DATETIME,ends_at DATETIME,usage_limit INT,active BOOLEAN DEFAULT TRUE);
CREATE TABLE support_tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,subject VARCHAR(255) NOT NULL,body TEXT NOT NULL,status ENUM('open','in_progress','resolved','closed') DEFAULT 'open',priority ENUM('low','normal','high','urgent') DEFAULT 'normal',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(order_id) REFERENCES orders(id));
